// <diletta-text-link> — a INSTÂNCIA WEB de `design-system-text-link`.
//
// A pintura vem de `pintura.g.js` (tabela medida no render do Dart). O sublinhado
// é eixo da spec e NÃO está na tabela de pintura, porque não é cor.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-text-link';
const TONE = ['brand', 'partner', 'neutro'];
const UNDERLINE = ['none', 'always', 'onHover'];

class DilettaTextLink extends HTMLElement {
  static observedAttributes = ['tone', 'underline', 'href', 'disabled'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  render() {
    const tone = eixo(this, 'tone', TONE, 'brand');
    const underline = eixo(this, 'underline', UNDERLINE, 'onHover');
    const papeis = papeisDe(SLUG, { Tone: tone });
    const href = this.getAttribute('href');
    const off = this.hasAttribute('disabled');

    // Sem `href` isto vira `<button>`, e não um `<a>` sem destino. Âncora sem
    // href não recebe foco de teclado nem é anunciada como link — é o caso que a
    // semana passada mediu no SDK: a peça parecia acionável e o teclado não a
    // alcançava.
    const tag = href && !off ? 'a' : 'button';
    const attrs = tag === 'a'
      ? `href="${href.replace(/"/g, '&quot;')}"`
      : `type="button"${off ? ' disabled' : ''}`;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline; }
        .link {
          ${estiloDa(papeis)}
          background: none; border-width: 0; padding: 0; margin: 0;
          font: inherit; cursor: pointer;
          text-decoration: ${underline === 'always' ? 'underline' : 'none'};
          text-underline-offset: 2px;
        }
        ${underline === 'onHover' ? '.link:hover { text-decoration: underline; }' : ''}
        .link:disabled { color: var(--cps-textDisabled); cursor: default; }
        /* 2.4.7 Focus Visible: o anel é do foco de TECLADO, e a espessura é a
           mesma que o Dart usa (DilettaFoco.espessura = 3). */
        .link:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <${tag} class="link" ${attrs}><slot></slot></${tag}>`;
  }
}

customElements.define('diletta-text-link', DilettaTextLink);
export { DilettaTextLink };
